    {
        var assembly = typeof(GeneratedBuiltInModels).Assembly;
        var resourceName = assembly
            .GetManifestResourceNames()
            .Single(name => name.EndsWith(".generated-models.seed.json", StringComparison.Ordinal));

        using var stream = assembly.GetManifestResourceStream(resourceName)
            ?? throw new InvalidOperationException($"Embedded model seed resource '{resourceName}' was not found.");
        using var document = JsonDocument.Parse(stream);

        if (!document.RootElement.TryGetProperty("providers", out var providers) ||
            providers.ValueKind != JsonValueKind.Object)
        {
            return new Dictionary<string, IReadOnlyDictionary<string, Model>>(StringComparer.OrdinalIgnoreCase);
        }

