            foreach (var modelElement in providerProperty.Value.EnumerateArray())
            {
                if (!TryReadModel(providerProperty.Name, modelElement, out var model))
                {
                    continue;
                }

                models[model.Id] = model;
            }

            if (models.Count > 0)
            {
                catalog[providerProperty.Name] = models;
            }
        }

        AddCompatibilityProviders(catalog);
        return catalog;
    }

